//! Writes, checks and gates the generated OpenRPC document.
//!
//! ```text
//! openrpc write <path>       write the generated document
//! openrpc check <path>       exit 1 unless <path> equals the generated bytes
//! openrpc compat <released>  exit 1 if the generated document breaks <released>
//! ```

use std::fs;
use std::io::{self, Write as _};
use std::path::PathBuf;
use std::process::ExitCode;

use ovis_terminal_protocol::schema::{SchemaError, check_compatibility, render_openrpc};
use serde_json::{Value, json};
use thiserror::Error;

/// Failure of one generator command.
#[derive(Debug, Error)]
enum CliError {
    #[error("expected `write <path>`, `check <path>` or `compat <released>`")]
    Usage,
    #[error("cannot access {path}")]
    Io {
        path: PathBuf,
        #[source]
        source: io::Error,
    },
    #[error("{path} differs from the generated document")]
    Stale { path: PathBuf },
    #[error(transparent)]
    Schema(#[from] SchemaError),
}

impl CliError {
    const fn kind(&self) -> &'static str {
        match self {
            Self::Usage => "usage",
            Self::Io { .. } => "io",
            Self::Stale { .. } => "schema_stale",
            Self::Schema(error) => error.kind(),
        }
    }

    const fn hint(&self) -> &'static str {
        match self {
            Self::Usage => "run with write, check or compat and one path",
            Self::Io { .. } => "check the path and its permissions",
            Self::Stale { .. } => "run `openrpc write` and commit the result",
            Self::Schema(error) => error.hint(),
        }
    }

    const fn exit_code(&self) -> u8 {
        match self {
            Self::Usage => 2,
            Self::Io { .. } | Self::Stale { .. } | Self::Schema(_) => 1,
        }
    }

    fn report(&self) -> Value {
        let breaks: Vec<Value> = match self {
            Self::Schema(SchemaError::Incompatible { breaks }) => breaks
                .iter()
                .map(|change| json!({ "path": change.path, "rule": change.rule.token() }))
                .collect(),
            Self::Usage | Self::Io { .. } | Self::Stale { .. } | Self::Schema(_) => Vec::new(),
        };
        json!({ "kind": self.kind(), "hint": self.hint(), "message": self.to_string(), "breaks": breaks })
    }
}

fn read(path: &PathBuf) -> Result<String, CliError> {
    fs::read_to_string(path).map_err(|source| CliError::Io {
        path: path.clone(),
        source,
    })
}

fn run(command: &str, path: PathBuf) -> Result<Value, CliError> {
    let generated = render_openrpc()?;
    match command {
        "write" => {
            fs::write(&path, &generated).map_err(|source| CliError::Io {
                path: path.clone(),
                source,
            })?;
            Ok(json!({ "written": path, "bytes": generated.len() }))
        }
        "check" => {
            if read(&path)? == generated {
                Ok(json!({ "fresh": path, "bytes": generated.len() }))
            } else {
                Err(CliError::Stale { path })
            }
        }
        "compat" => {
            let released: Value = serde_json::from_str(&read(&path)?).map_err(SchemaError::from)?;
            let current: Value = serde_json::from_str(&generated).map_err(SchemaError::from)?;
            check_compatibility(&released, &current)?;
            Ok(json!({ "compatible_with": path }))
        }
        _ => Err(CliError::Usage),
    }
}

fn main() -> ExitCode {
    let mut args = std::env::args().skip(1);
    let outcome = match (args.next(), args.next(), args.next()) {
        (Some(command), Some(path), None) => run(&command, PathBuf::from(path)),
        _ => Err(CliError::Usage),
    };
    let (written, code) = match outcome {
        Ok(report) => (writeln!(io::stdout().lock(), "{report}"), ExitCode::SUCCESS),
        Err(error) => (
            writeln!(io::stderr().lock(), "{}", error.report()),
            ExitCode::from(error.exit_code()),
        ),
    };
    match written {
        Ok(()) => code,
        Err(_) => ExitCode::FAILURE,
    }
}
